window.onload=init();let map=L.map("map").setView([46.866,3.333],6);function init(){let e=localStorage.getItem("theme");e&&updateTheme(e),fetch("../json/promo.json").then(e=>e.json()).then(e=>updateInformations(e))}function updateTheme(e){document.documentElement.setAttribute("data-bs-theme",e)}function setMarkers(e){e.forEach(e=>{if(e.coord){let t=e.coord.latitude,o=e.coord.longitude,n=`${e.lastname} ${e.name}`,a=L.marker([t,o]);a.bindPopup(n),a.addTo(map)}})}function updateInformations(e){document.querySelector("h1[nomPromo]").innerText=e.nomPromo}L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map),fetch("../json/promo.json").then(e=>e.json()).then(e=>setMarkers(e.apprenants));